insert into public.authors (id, name, born, died, approx, movement, bio, quote, featured, portrait, scene, position) values
    ('epictetus', '{"az":"Epiktet","en":"Epictetus","ru":"Эпиктет"}'::jsonb, 50, 135, true, '{"az":"Stoisizm","en":"Stoicism","ru":"Стоицизм"}'::jsonb, '{"az":"Frigiyada qul kimi doğulmuş stoik filosof. Azad edildikdən sonra Nikopolda məktəb açıb, təlimini şagirdi Arrian qələmə alıb.","en":"A Stoic philosopher born into slavery in Phrygia. Once freed he opened a school in Nicopolis; his pupil Arrian wrote down his teaching.","ru":"Философ-стоик, рождённый рабом во Фригии. Получив свободу, открыл школу в Никополе; его учение записал ученик Арриан."}'::jsonb, '{"text":"Ταράσσει τοὺς ἀνθρώπους οὐ τὰ πράγματα, ἀλλὰ τὰ περὶ τῶν πραγμάτων δόγματα.","lang":"grc","translation":{"az":"İnsanları şeylərin özü deyil, onlar haqqındakı rəyləri narahat edir.","en":"Men are disturbed not by things, but by the opinions they hold about things.","ru":"Людей мучают не вещи, а представления о вещах."}}'::jsonb, 1, '/authors/epictetus.webp', '/scenes/epictetus.webp', 0),
    ('plato', '{"az":"Platon","en":"Plato","ru":"Платон"}'::jsonb, -427, -347, false, '{"az":"Antik fəlsəfə","en":"Ancient philosophy","ru":"Античная философия"}'::jsonb, '{"az":"Sokratın şagirdi və Afinada Akademiyanın banisi. Ədalət, sevgi və bilik haqqında dialoqları iki min ildən çoxdur oxunur.","en":"Pupil of Socrates and founder of the Academy in Athens. His dialogues on justice, love and knowledge have been read for over two thousand years.","ru":"Ученик Сократа и основатель Академии в Афинах. Его диалоги о справедливости, любви и знании читают уже более двух тысяч лет."}'::jsonb, '{"text":"ὁ δὲ ἀνεξέταστος βίος οὐ βιωτὸς ἀνθρώπῳ.","lang":"grc","translation":{"az":"Sınanmamış həyat insan üçün yaşamağa dəyməz.","en":"The unexamined life is not worth living for a human being.","ru":"Жизнь без исследования не есть жизнь для человека."}}'::jsonb, 2, '/authors/plato.webp', '/scenes/plato.webp', 1),
    ('hegel', '{"az":"Georq Hegel","en":"G. W. F. Hegel","ru":"Георг Гегель"}'::jsonb, 1770, 1831, false, '{"az":"Alman idealizmi","en":"German idealism","ru":"Немецкий идеализм"}'::jsonb, '{"az":"Alman idealizminin zirvəsi. Tarixi ruhun öz azadlığını dərk etməyə doğru dialektik yolu kimi təsvir edib.","en":"The summit of German idealism. He described history as the dialectical path of spirit towards knowing its own freedom.","ru":"Вершина немецкого идеализма. Описал историю как диалектический путь духа к осознанию собственной свободы."}'::jsonb, '{"text":"Was vernünftig ist, das ist wirklich; und was wirklich ist, das ist vernünftig.","lang":"de","translation":{"az":"Ağlabatan olan həqiqidir, həqiqi olan isə ağlabatandır.","en":"What is rational is actual, and what is actual is rational.","ru":"Что разумно, то действительно; и что действительно, то разумно."}}'::jsonb, 3, '/authors/hegel.webp', '/scenes/hegel.webp', 2),
    ('dostoevsky', '{"az":"Fyodor Dostoyevski","en":"Fyodor Dostoevsky","ru":"Фёдор Достоевский"}'::jsonb, 1821, 1881, false, '{"az":"Rus realizmi","en":"Russian realism","ru":"Русский реализм"}'::jsonb, '{"az":"Rus romançısı. Günah, inam və azad iradə ilə mübarizə aparan insan ruhunu ədəbiyyatın mərkəzinə qoyub.","en":"Russian novelist who placed the human soul, wrestling with guilt, faith and free will, at the centre of literature.","ru":"Русский романист, поставивший в центр литературы человеческую душу, борющуюся с виной, верой и свободой воли."}'::jsonb, '{"text":"Красота спасёт мир.","lang":"ru","translation":{"az":"Gözəllik dünyanı xilas edəcək.","en":"Beauty will save the world.","ru":"Красота спасёт мир."}}'::jsonb, 4, '/authors/dostoevsky.webp', '/scenes/dostoevsky.webp', 3),
    ('freud', '{"az":"Ziqmund Freyd","en":"Sigmund Freud","ru":"Зигмунд Фрейд"}'::jsonb, 1856, 1939, false, '{"az":"Psixoanaliz","en":"Psychoanalysis","ru":"Психоанализ"}'::jsonb, '{"az":"Vyanalı nevroloq, psixoanalizin banisi. Yuxuların, unutqanlığın və arzuların arxasında şüursuzun işlədiyini göstərib.","en":"Viennese neurologist and founder of psychoanalysis. He showed the unconscious at work behind dreams, slips and desires.","ru":"Венский невролог, основатель психоанализа. Показал работу бессознательного за сновидениями, оговорками и желаниями."}'::jsonb, '{"text":"Wo Es war, soll Ich werden.","lang":"de","translation":{"az":"«O» olan yerdə «Mən» olmalıdır.","en":"Where id was, there ego shall be.","ru":"Где было Оно, должно стать Я."}}'::jsonb, 5, '/authors/freud.webp', '/scenes/freud.webp', 4),
    ('nietzsche', '{"az":"Fridrix Nitsşe","en":"Friedrich Nietzsche","ru":"Фридрих Ницше"}'::jsonb, 1844, 1900, false, '{"az":"Həyat fəlsəfəsi","en":"Philosophy of life","ru":"Философия жизни"}'::jsonb, '{"az":"Alman filosofu və filoloqu. Əxlaqın mənşəyini sorğulayıb, insanı öz dəyərlərini yaratmağa çağırıb.","en":"German philosopher and philologist who questioned the origins of morality and called on people to create their own values.","ru":"Немецкий философ и филолог. Поставил под вопрос происхождение морали и призвал человека создавать собственные ценности."}'::jsonb, '{"text":"Hat man sein warum? des Lebens, so verträgt man sich fast mit jedem wie?","lang":"de","translation":{"az":"Yaşamaq üçün «niyə»si olan, demək olar ki, hər «necə»yə dözər.","en":"He who has a why to live can bear almost any how.","ru":"У кого есть «зачем» жить, тот вынесет почти любое «как»."}}'::jsonb, 6, '/authors/nietzsche.webp', '/scenes/nietzsche.webp', 5),
    ('tolstoy', '{"az":"Lev Tolstoy","en":"Leo Tolstoy","ru":"Лев Толстой"}'::jsonb, 1828, 1910, false, '{"az":"Rus realizmi","en":"Russian realism","ru":"Русский реализм"}'::jsonb, '{"az":"Rus yazıçısı və mütəfəkkiri. Romanlarında tarixin axınını ayrı-ayrı insanların taleyi ilə birləşdirib.","en":"Russian writer and thinker whose novels join the sweep of history to the fate of single lives.","ru":"Русский писатель и мыслитель. В его романах ход истории сплетается с судьбами отдельных людей."}'::jsonb, '{"text":"Все счастливые семьи похожи друг на друга, каждая несчастливая семья несчастлива по-своему.","lang":"ru","translation":{"az":"Bütün xoşbəxt ailələr bir-birinə bənzəyir, hər bədbəxt ailə isə öz yolu ilə bədbəxtdir.","en":"All happy families are alike; each unhappy family is unhappy in its own way.","ru":"Все счастливые семьи похожи друг на друга, каждая несчастливая семья несчастлива по-своему."}}'::jsonb, 7, '/authors/tolstoy.webp', '/scenes/tolstoy.webp', 6),
    ('camus', '{"az":"Alber Kamyu","en":"Albert Camus","ru":"Альбер Камю"}'::jsonb, 1913, 1960, false, '{"az":"Absurd fəlsəfəsi","en":"Philosophy of the absurd","ru":"Философия абсурда"}'::jsonb, '{"az":"Fransız yazıçısı və filosofu, Nobel mükafatı laureatı. Mənasız görünən dünyada insanın üsyanını və ləyaqətini yazıb.","en":"French writer and philosopher, Nobel laureate, who wrote of human revolt and dignity in a world that seems to have no meaning.","ru":"Французский писатель и философ, лауреат Нобелевской премии. Писал о бунте и достоинстве человека в мире, лишённом смысла."}'::jsonb, '{"text":"Il faut imaginer Sisyphe heureux.","lang":"fr","translation":{"az":"Sizifi xoşbəxt təsəvvür etmək lazımdır.","en":"One must imagine Sisyphus happy.","ru":"Сизифа следует представлять себе счастливым."}}'::jsonb, 8, '/authors/camus.webp', '/scenes/camus.webp', 7),
    ('kant', '{"az":"İmmanuel Kant","en":"Immanuel Kant","ru":"Иммануил Кант"}'::jsonb, 1724, 1804, false, '{"az":"Alman klassik fəlsəfəsi","en":"German classical philosophy","ru":"Немецкая классическая философия"}'::jsonb, '{"az":"Kenqsberqli filosof. Biliyin hüdudlarını müəyyən edib, əxlaqı ağlın öz qanunu üzərində qurub.","en":"Philosopher of Königsberg who set out the limits of knowledge and founded morality on reason''s own law.","ru":"Кёнигсбергский философ. Определил границы познания и основал мораль на собственном законе разума."}'::jsonb, '{"text":"Habe Mut, dich deines eigenen Verstandes zu bedienen!","lang":"de","translation":{"az":"Öz ağlından istifadə etməyə cəsarətin olsun!","en":"Have courage to use your own understanding!","ru":"Имей мужество пользоваться собственным умом!"}}'::jsonb, 9, '/authors/kant.webp', '/scenes/kant.webp', 8),
    ('descartes', '{"az":"Rene Dekart","en":"René Descartes","ru":"Рене Декарт"}'::jsonb, 1596, 1650, false, '{"az":"Rasionalizm","en":"Rationalism","ru":"Рационализм"}'::jsonb, '{"az":"Fransız filosofu və riyaziyyatçısı. Hər şeyə şübhədən başlayaraq yeni fəlsəfənin əsasını qoyub.","en":"French philosopher and mathematician who began from doubting everything and laid the foundation of modern philosophy.","ru":"Французский философ и математик. Начав с сомнения во всём, заложил основы философии Нового времени."}'::jsonb, '{"text":"Je pense, donc je suis.","lang":"fr","translation":{"az":"Düşünürəm, deməli, varam.","en":"I think, therefore I am.","ru":"Я мыслю, следовательно, существую."}}'::jsonb, 10, '/authors/descartes.webp', '/scenes/descartes.webp', 9),
    ('kafka', '{"az":"Frans Kafka","en":"Franz Kafka","ru":"Франц Кафка"}'::jsonb, 1883, 1924, false, '{"az":"Modernizm","en":"Modernism","ru":"Модернизм"}'::jsonb, '{"az":"Praqalı yazıçı. Bürokratiyanın labirintində itən, səbəbini bilmədən günahlandırılan insanı təsvir edib.","en":"Prague writer of people lost in the labyrinth of bureaucracy, accused without ever learning why.","ru":"Пражский писатель. Изобразил человека, потерянного в лабиринте бюрократии и обвинённого без объяснения причин."}'::jsonb, '{"text":"Ein Buch muss die Axt sein für das gefrorene Meer in uns.","lang":"de","translation":{"az":"Kitab içimizdəki donmuş dənizi sındıran balta olmalıdır.","en":"A book must be the axe for the frozen sea within us.","ru":"Книга должна быть топором для замёрзшего моря внутри нас."}}'::jsonb, 11, '/authors/kafka.webp', '/scenes/kafka.webp', 10),
    ('aristotle', '{"az":"Aristotel","en":"Aristotle","ru":"Аристотель"}'::jsonb, -384, -322, false, '{"az":"Antik fəlsəfə","en":"Ancient philosophy","ru":"Античная философия"}'::jsonb, '{"az":"Platonun şagirdi və Makedoniyalı İsgəndərin müəllimi. Məntiqdən siyasətə qədər demək olar ki, hər elmin təməlini qoyub.","en":"Pupil of Plato and tutor of Alexander the Great, he laid the foundations of almost every science from logic to politics.","ru":"Ученик Платона и наставник Александра Македонского. Заложил основы почти всех наук — от логики до политики."}'::jsonb, null, null, null, null, 11),
    ('marcus-aurelius', '{"az":"Mark Avreli","en":"Marcus Aurelius","ru":"Марк Аврелий"}'::jsonb, 121, 180, false, '{"az":"Stoisizm","en":"Stoicism","ru":"Стоицизм"}'::jsonb, '{"az":"Roma imperatoru və stoik filosof. Hərbi yürüşlər zamanı öz-özünə yazdığı qeydlər fəlsəfənin ən səmimi kitablarından birinə çevrilib.","en":"Roman emperor and Stoic whose private notes, written on campaign, became one of philosophy''s most candid books.","ru":"Римский император и стоик. Его личные записи, сделанные в походах, стали одной из самых искренних книг философии."}'::jsonb, null, null, null, null, 12),
    ('seneca', '{"az":"Seneka","en":"Seneca","ru":"Сенека"}'::jsonb, -4, 65, true, '{"az":"Stoisizm","en":"Stoicism","ru":"Стоицизм"}'::jsonb, '{"az":"Roma stoiki, natiq və Neronun müşaviri. Zamanın, ölümün və dostluğun mənası haqqında məktubları bu gün də aktualdır.","en":"Roman Stoic, orator and adviser to Nero, whose letters on time, death and friendship still speak today.","ru":"Римский стоик, оратор и советник Нерона. Его письма о времени, смерти и дружбе актуальны и сегодня."}'::jsonb, null, null, null, null, 13),
    ('spinoza', '{"az":"Barux Spinoza","en":"Baruch Spinoza","ru":"Бенедикт Спиноза"}'::jsonb, 1632, 1677, false, '{"az":"Rasionalizm","en":"Rationalism","ru":"Рационализм"}'::jsonb, '{"az":"Amsterdamlı filosof, linza cilalayaraq dolanıb. Tanrını və təbiəti vahid substansiya kimi həndəsi metodla izah edib.","en":"Amsterdam philosopher who earned his living grinding lenses and explained God and nature as one substance, in geometric order.","ru":"Амстердамский философ, зарабатывавший шлифовкой линз. Геометрическим методом описал Бога и природу как единую субстанцию."}'::jsonb, null, null, null, null, 14),
    ('kierkegaard', '{"az":"Sören Kyerkeqor","en":"Søren Kierkegaard","ru":"Сёрен Кьеркегор"}'::jsonb, 1813, 1855, false, '{"az":"Ekzistensializm","en":"Existentialism","ru":"Экзистенциализм"}'::jsonb, '{"az":"Danimarkalı filosof və ilahiyyatçı. Seçim, iztirab və imanı fərdin daxili təcrübəsi kimi araşdıraraq ekzistensializmin yolunu açıb.","en":"Danish philosopher and theologian who explored choice, anxiety and faith as inward experience and opened the way to existentialism.","ru":"Датский философ и богослов. Исследовал выбор, тревогу и веру как внутренний опыт личности и открыл путь экзистенциализму."}'::jsonb, null, null, null, null, 15),
    ('herodotus', '{"az":"Herodot","en":"Herodotus","ru":"Геродот"}'::jsonb, -484, -425, true, '{"az":"Antik tarixşünaslıq","en":"Ancient historiography","ru":"Античная историография"}'::jsonb, '{"az":"Halikarnaslı yunan tarixçisi, «tarixin atası». Yunan-fars müharibələrini və gördüyü xalqların adətlərini qələmə alıb.","en":"Greek historian from Halicarnassus, the \"father of history\", who recorded the Greco-Persian Wars and the customs of the peoples he met.","ru":"Греческий историк из Галикарнаса, «отец истории». Описал греко-персидские войны и обычаи народов, которых видел."}'::jsonb, null, null, null, null, 16),
    ('thucydides', '{"az":"Fukidid","en":"Thucydides","ru":"Фукидид"}'::jsonb, -460, -400, true, '{"az":"Antik tarixşünaslıq","en":"Ancient historiography","ru":"Античная историография"}'::jsonb, '{"az":"Afinalı sərkərdə və tarixçi. Peloponnes müharibəsini şahid kimi təsvir edib, hadisələrin səbəbini tanrılarda deyil, insanlarda axtarıb.","en":"Athenian general and historian who chronicled the Peloponnesian War as a witness and looked for causes in people, not gods.","ru":"Афинский стратег и историк. Описал Пелопоннесскую войну как очевидец и искал причины событий в людях, а не в богах."}'::jsonb, null, null, null, null, 17),
    ('plutarch', '{"az":"Plutarx","en":"Plutarch","ru":"Плутарх"}'::jsonb, 46, 119, true, '{"az":"Antik tarixşünaslıq","en":"Ancient historiography","ru":"Античная историография"}'::jsonb, '{"az":"Xeroneyalı yunan yazıçısı. Yunan və Roma böyüklərini cüt-cüt müqayisə edərək xarakterin tarixdəki rolunu göstərib.","en":"Greek writer from Chaeronea who paired the great men of Greece and Rome to show the part character plays in history.","ru":"Греческий писатель из Херонеи. Сравнивая великих греков и римлян попарно, показал роль характера в истории."}'::jsonb, null, null, null, null, 18),
    ('tacitus', '{"az":"Tatsit","en":"Tacitus","ru":"Тацит"}'::jsonb, 56, 120, true, '{"az":"Antik tarixşünaslıq","en":"Ancient historiography","ru":"Античная историография"}'::jsonb, '{"az":"Roma senatoru və tarixçisi. İmperatorların hakimiyyətini sərt və yığcam üslubla təsvir edib.","en":"Roman senator and historian who portrayed the rule of the emperors in a stern, compressed style.","ru":"Римский сенатор и историк. Описал правление императоров суровым и сжатым слогом."}'::jsonb, null, null, null, null, 19),
    ('caesar', '{"az":"Yuli Sezar","en":"Julius Caesar","ru":"Юлий Цезарь"}'::jsonb, -100, -44, false, '{"az":"Antik tarixşünaslıq","en":"Ancient historiography","ru":"Античная историография"}'::jsonb, '{"az":"Roma sərkərdəsi və diktatoru. Qalliyadakı yürüşlərini üçüncü şəxsdə, aydın və soyuqqanlı nəsrlə özü yazıb.","en":"Roman general and dictator who wrote his own account of the Gallic campaigns in clear, cool third-person prose.","ru":"Римский полководец и диктатор. Сам описал свои галльские походы — ясной, сдержанной прозой от третьего лица."}'::jsonb, null, null, null, null, 20),
    ('ibn-khaldun', '{"az":"İbn Xaldun","en":"Ibn Khaldun","ru":"Ибн Хальдун"}'::jsonb, 1332, 1406, false, '{"az":"Orta əsrlər İslam düşüncəsi","en":"Medieval Islamic thought","ru":"Средневековая исламская мысль"}'::jsonb, '{"az":"Tunisli alim və dövlət xadimi. Dövlətlərin yüksəliş və tənəzzülünü izah edərək sosiologiyanın sələfi sayılır.","en":"Tunisian scholar and statesman whose account of the rise and fall of states makes him a forerunner of sociology.","ru":"Тунисский учёный и государственный деятель. Объяснив возвышение и упадок государств, считается предтечей социологии."}'::jsonb, null, null, null, null, 21),
    ('machiavelli', '{"az":"Nikkolo Makiavelli","en":"Niccolò Machiavelli","ru":"Никколо Макиавелли"}'::jsonb, 1469, 1527, false, '{"az":"İntibah siyasi fikri","en":"Renaissance political thought","ru":"Политическая мысль Возрождения"}'::jsonb, '{"az":"Florensiyalı diplomat. Siyasəti əxlaqi arzulara görə deyil, olduğu kimi təsvir edən ilk müəlliflərdəndir.","en":"Florentine diplomat, among the first to describe politics as it is rather than as morality wishes it to be.","ru":"Флорентийский дипломат, одним из первых описавший политику такой, какая она есть, а не какой её хочет видеть мораль."}'::jsonb, null, null, null, null, 22),
    ('gibbon', '{"az":"Edvard Gibbon","en":"Edward Gibbon","ru":"Эдуард Гиббон"}'::jsonb, 1737, 1794, false, '{"az":"Maarifçilik tarixşünaslığı","en":"Enlightenment historiography","ru":"Историография Просвещения"}'::jsonb, '{"az":"İngilis tarixçisi. Roma imperiyasının min illik tənəzzülünü ironiya və dərin araşdırma ilə izləyib.","en":"English historian who traced a thousand years of Rome''s decline with irony and deep research.","ru":"Английский историк. С иронией и глубиной исследования проследил тысячелетний упадок Римской империи."}'::jsonb, null, null, null, null, 23),
    ('tocqueville', '{"az":"Aleksis de Tokvil","en":"Alexis de Tocqueville","ru":"Алексис де Токвиль"}'::jsonb, 1805, 1859, false, '{"az":"Siyasi fəlsəfə","en":"Political philosophy","ru":"Политическая философия"}'::jsonb, '{"az":"Fransız siyasətçisi və mütəfəkkiri. Amerikaya səyahətindən sonra demokratiyanın güclü və təhlükəli tərəflərini təhlil edib.","en":"French statesman and thinker who, after travelling in America, analysed the strengths and dangers of democracy.","ru":"Французский политик и мыслитель. После поездки в Америку проанализировал сильные и опасные стороны демократии."}'::jsonb, null, null, null, null, 24),
    ('marco-polo', '{"az":"Marko Polo","en":"Marco Polo","ru":"Марко Поло"}'::jsonb, 1254, 1324, false, '{"az":"Səyahətnamə","en":"Travel writing","ru":"Путевые записки"}'::jsonb, '{"az":"Venesiyalı tacir. İpək yolu ilə Xubilay xanın sarayına qədər səyahəti Avropaya Şərqi yeni gözlə göstərib.","en":"Venetian merchant whose journey along the Silk Road to the court of Kublai Khan showed Europe the East anew.","ru":"Венецианский купец. Его путешествие по Шёлковому пути ко двору Хубилая открыло Европе Восток."}'::jsonb, null, null, null, null, 25),
    ('xenophon', '{"az":"Ksenofont","en":"Xenophon","ru":"Ксенофонт"}'::jsonb, -430, -354, true, '{"az":"Antik tarixşünaslıq","en":"Ancient historiography","ru":"Античная историография"}'::jsonb, '{"az":"Afinalı sərkərdə və Sokratın şagirdi. On min yunan muzdlusunun Asiyadan dənizə geri çəkilişinə özü rəhbərlik edib.","en":"Athenian soldier and pupil of Socrates who helped lead ten thousand Greek mercenaries back from Asia to the sea.","ru":"Афинский полководец и ученик Сократа. Сам вёл десять тысяч греческих наёмников из глубин Азии к морю."}'::jsonb, null, null, null, null, 26),
    ('suetonius', '{"az":"Svetoni","en":"Suetonius","ru":"Светоний"}'::jsonb, 69, 122, true, '{"az":"Antik tarixşünaslıq","en":"Ancient historiography","ru":"Античная историография"}'::jsonb, '{"az":"Roma tarixçisi və imperator Adrianın katibi. Sezarların həyatını sarayın gizli detalları ilə birlikdə yazıb.","en":"Roman historian and secretary to Hadrian who wrote the lives of the Caesars along with the secrets of their court.","ru":"Римский историк и секретарь императора Адриана. Описал жизнь цезарей вместе с тайнами их двора."}'::jsonb, null, null, null, null, 27),
    ('livy', '{"az":"Titus Livi","en":"Livy","ru":"Тит Ливий"}'::jsonb, -59, 17, false, '{"az":"Antik tarixşünaslıq","en":"Ancient historiography","ru":"Античная историография"}'::jsonb, '{"az":"Patavayalı Roma tarixçisi. Romanın tarixini şəhərin əfsanəvi qurulmasından öz dövrünə qədər yüz qırx iki kitabda danışıb.","en":"Roman historian from Patavium who told Rome''s story from its legendary founding to his own day in 142 books.","ru":"Римский историк из Патавия. Рассказал историю Рима от легендарного основания до своих дней в ста сорока двух книгах."}'::jsonb, null, null, null, null, 28),
    ('procopius', '{"az":"Prokopi","en":"Procopius","ru":"Прокопий Кесарийский"}'::jsonb, 500, 565, true, '{"az":"Bizans tarixşünaslığı","en":"Byzantine historiography","ru":"Византийская историография"}'::jsonb, '{"az":"Qeysəriyyəli Bizans tarixçisi. Yustinianın müharibələrini rəsmi şəkildə, sarayın qalmaqallarını isə gizlində yazıb.","en":"Byzantine historian from Caesarea who chronicled Justinian''s wars officially and the scandals of his court in secret.","ru":"Византийский историк из Кесарии. Официально описал войны Юстиниана, а тайно — скандалы его двора."}'::jsonb, null, null, null, null, 29),
    ('jung', '{"az":"Karl Qustav Yunq","en":"Carl Gustav Jung","ru":"Карл Густав Юнг"}'::jsonb, 1875, 1961, false, '{"az":"Analitik psixologiya","en":"Analytical psychology","ru":"Аналитическая психология"}'::jsonb, '{"az":"İsveçrəli psixiatr. Kollektiv şüursuzluq və arxetiplər ideyası ilə miflər, yuxular və dinlər arasında körpü salıb.","en":"Swiss psychiatrist whose ideas of the collective unconscious and archetypes linked myths, dreams and religions.","ru":"Швейцарский психиатр. Идеями коллективного бессознательного и архетипов связал мифы, сновидения и религии."}'::jsonb, null, null, null, null, 30),
    ('adler', '{"az":"Alfred Adler","en":"Alfred Adler","ru":"Альфред Адлер"}'::jsonb, 1870, 1937, false, '{"az":"Fərdi psixologiya","en":"Individual psychology","ru":"Индивидуальная психология"}'::jsonb, '{"az":"Avstriyalı psixoloq. Aşağılıq hissini və ona qarşı mübarizəni insan davranışının əsas qüvvəsi sayıb.","en":"Austrian psychologist who saw the feeling of inferiority, and the striving to overcome it, as the main force behind behaviour.","ru":"Австрийский психолог. Считал чувство неполноценности и стремление его преодолеть главной силой поведения."}'::jsonb, null, null, null, null, 31),
    ('frankl', '{"az":"Viktor Frankl","en":"Viktor Frankl","ru":"Виктор Франкл"}'::jsonb, 1905, 1997, false, '{"az":"Loqoterapiya","en":"Logotherapy","ru":"Логотерапия"}'::jsonb, '{"az":"Vyanalı psixiatr, nasist düşərgələrindən sağ çıxıb. Mənanın insanı ən ağır şəraitdə belə ayaqda saxladığını göstərib.","en":"Viennese psychiatrist and survivor of the Nazi camps who showed that meaning keeps a person standing in the worst conditions.","ru":"Венский психиатр, переживший нацистские лагеря. Показал, что смысл удерживает человека даже в самых тяжёлых условиях."}'::jsonb, null, null, null, null, 32),
    ('fromm', '{"az":"Erix Fromm","en":"Erich Fromm","ru":"Эрих Фромм"}'::jsonb, 1900, 1980, false, '{"az":"Humanist psixoanaliz","en":"Humanistic psychoanalysis","ru":"Гуманистический психоанализ"}'::jsonb, '{"az":"Alman-amerikan psixoloqu və filosofu. Sevgini, azadlığı və müasir cəmiyyətin insana təsirini araşdırıb.","en":"German-American psychologist and philosopher who studied love, freedom and what modern society does to people.","ru":"Немецко-американский психолог и философ. Исследовал любовь, свободу и влияние современного общества на человека."}'::jsonb, null, null, null, null, 33),
    ('william-james', '{"az":"Uilyam Ceyms","en":"William James","ru":"Уильям Джеймс"}'::jsonb, 1842, 1910, false, '{"az":"Funksionalizm","en":"Functionalism","ru":"Функционализм"}'::jsonb, '{"az":"Amerikan psixologiyasının atası və praqmatizmin banilərindən. Şüuru dayanmadan axan bir çay kimi təsvir edib.","en":"Father of American psychology and a founder of pragmatism, who described consciousness as a ceaselessly flowing stream.","ru":"Отец американской психологии и один из основателей прагматизма. Описал сознание как непрерывно текущий поток."}'::jsonb, null, null, null, null, 34),
    ('horney', '{"az":"Karen Horni","en":"Karen Horney","ru":"Карен Хорни"}'::jsonb, 1885, 1952, false, '{"az":"Neofreydizm","en":"Neo-Freudianism","ru":"Неофрейдизм"}'::jsonb, '{"az":"Alman-amerikan psixoanalitiki. Nevrozun kökünü bioloji instinktlərdə deyil, mədəniyyətdə və münasibətlərdə axtarıb.","en":"German-American psychoanalyst who looked for the roots of neurosis in culture and relationships, not biological instinct.","ru":"Немецко-американский психоаналитик. Искала корни невроза в культуре и отношениях, а не в биологических инстинктах."}'::jsonb, null, null, null, null, 35),
    ('le-bon', '{"az":"Qustav Lebon","en":"Gustave Le Bon","ru":"Гюстав Лебон"}'::jsonb, 1841, 1931, false, '{"az":"Sosial psixologiya","en":"Social psychology","ru":"Социальная психология"}'::jsonb, '{"az":"Fransız həkimi və sosioloqu. Kütlənin içində fərdin necə dəyişdiyini təsvir edən ilk müəlliflərdəndir.","en":"French physician and sociologist, one of the first to describe how a person changes inside a crowd.","ru":"Французский врач и социолог. Одним из первых описал, как меняется человек внутри толпы."}'::jsonb, null, null, null, null, 36),
    ('pavlov', '{"az":"İvan Pavlov","en":"Ivan Pavlov","ru":"Иван Павлов"}'::jsonb, 1849, 1936, false, '{"az":"Fiziologiya","en":"Physiology","ru":"Физиология"}'::jsonb, '{"az":"Rus fizioloqu, Nobel mükafatı laureatı. Şərti refleksləri kəşf edərək davranışın eksperimental öyrənilməsinin əsasını qoyub.","en":"Russian physiologist and Nobel laureate whose discovery of conditioned reflexes founded the experimental study of behaviour.","ru":"Русский физиолог, лауреат Нобелевской премии. Открыв условные рефлексы, заложил основы экспериментального изучения поведения."}'::jsonb, null, null, null, null, 37),
    ('maslow', '{"az":"Abraham Maslou","en":"Abraham Maslow","ru":"Абрахам Маслоу"}'::jsonb, 1908, 1970, false, '{"az":"Humanist psixologiya","en":"Humanistic psychology","ru":"Гуманистическая психология"}'::jsonb, '{"az":"Amerikan psixoloqu. Ehtiyaclar iyerarxiyası və özünüreallaşdırma ideyası ilə tanınır.","en":"American psychologist known for the hierarchy of needs and the idea of self-actualisation.","ru":"Американский психолог, известный иерархией потребностей и идеей самоактуализации."}'::jsonb, null, null, null, null, 38),
    ('erikson', '{"az":"Erik Erikson","en":"Erik Erikson","ru":"Эрик Эриксон"}'::jsonb, 1902, 1994, false, '{"az":"İnkişaf psixologiyası","en":"Developmental psychology","ru":"Психология развития"}'::jsonb, '{"az":"Alman-amerikan psixoanalitiki. İnsan həyatını səkkiz psixososial mərhələdən ibarət yol kimi təsvir edib.","en":"German-American psychoanalyst who described human life as a path through eight psychosocial stages.","ru":"Немецко-американский психоаналитик. Описал жизнь человека как путь через восемь психосоциальных стадий."}'::jsonb, null, null, null, null, 39),
    ('homer', '{"az":"Homer","en":"Homer","ru":"Гомер"}'::jsonb, -800, -700, true, '{"az":"Antik epos","en":"Ancient epic","ru":"Античный эпос"}'::jsonb, '{"az":"Qədim yunan ozanı, Avropa ədəbiyyatının ilk böyük poemalarının müəllifi sayılır.","en":"Ancient Greek bard, held to be the author of the first great poems of European literature.","ru":"Древнегреческий сказитель, которому приписывают первые великие поэмы европейской литературы."}'::jsonb, null, null, null, null, 40),
    ('dante', '{"az":"Dante Aligyeri","en":"Dante Alighieri","ru":"Данте Алигьери"}'::jsonb, 1265, 1321, false, '{"az":"Orta əsrlər poeziyası","en":"Medieval poetry","ru":"Средневековая поэзия"}'::jsonb, '{"az":"Florensiyalı şair. Cəhənnəmdən cənnətə səyahətini xalq dilində yazaraq italyan ədəbi dilini yaradıb.","en":"Florentine poet who wrote his journey from Hell to Paradise in the vernacular and so created literary Italian.","ru":"Флорентийский поэт. Описав путешествие из Ада в Рай на народном языке, создал итальянский литературный язык."}'::jsonb, null, null, null, null, 41),
    ('cervantes', '{"az":"Migel de Servantes","en":"Miguel de Cervantes","ru":"Мигель де Сервантес"}'::jsonb, 1547, 1616, false, '{"az":"İspan Qızıl əsri","en":"Spanish Golden Age","ru":"Испанский золотой век"}'::jsonb, '{"az":"İspan yazıçısı və əsgəri. Cəngavərlik romanlarını parodiya edərkən ilk müasir romanı yaradıb.","en":"Spanish writer and soldier who, while parodying chivalric romances, created the first modern novel.","ru":"Испанский писатель и солдат. Пародируя рыцарские романы, создал первый роман Нового времени."}'::jsonb, null, null, null, null, 42),
    ('nizami', '{"az":"Nizami Gəncəvi","en":"Nizami Ganjavi","ru":"Низами Гянджеви"}'::jsonb, 1141, 1209, false, '{"az":"Klassik Şərq poeziyası","en":"Classical Eastern poetry","ru":"Классическая восточная поэзия"}'::jsonb, '{"az":"Gəncəli dahi şair. «Xəmsə»si ilə Şərq poemasının zirvəsini yaradıb, sevgi və ədaləti fəlsəfi dərinliklə tərənnüm edib.","en":"The great poet of Ganja whose Khamsa is a summit of Eastern narrative poetry, singing love and justice with philosophical depth.","ru":"Великий поэт из Гянджи. Его «Хамсе» — вершина восточной поэмы, воспевающая любовь и справедливость с философской глубиной."}'::jsonb, null, null, null, null, 43),
    ('fuzuli', '{"az":"Məhəmməd Füzuli","en":"Muhammad Fuzuli","ru":"Мухаммед Физули"}'::jsonb, 1494, 1556, false, '{"az":"Klassik Şərq poeziyası","en":"Classical Eastern poetry","ru":"Классическая восточная поэзия"}'::jsonb, '{"az":"Azərbaycan şairi, Bağdadda yaşayıb. Azərbaycan, fars və ərəb dillərində yazıb, eşqin iztirabını lirikanın zirvəsinə qaldırıb.","en":"Azerbaijani poet who lived in Baghdad and wrote in Azerbaijani, Persian and Arabic, raising the anguish of love to the height of lyric poetry.","ru":"Азербайджанский поэт, живший в Багдаде. Писал на азербайджанском, персидском и арабском, возведя страдание любви на вершину лирики."}'::jsonb, null, null, null, null, 44)
insert into public.books (id, author_id, category, title, description, price, old_price, stock, pages, year, approx_year, ornament, tag, cover_image, position) values
    ('the-republic', 'plato', 'philosophy', '{"az":"Dövlət","en":"The Republic","ru":"Государство"}'::jsonb, '{"az":"Ədalət nədir və ideal dövlət necə qurulmalıdır? Mağara alleqoriyası da daxil olmaqla Qərb fəlsəfəsinin təməl dialoqu.","en":"What is justice, and how should the ideal state be built? The founding dialogue of Western philosophy, cave allegory included.","ru":"Что такое справедливость и каким должно быть идеальное государство? Основополагающий диалог западной философии, включая миф о пещере."}'::jsonb, 18.9, null, 24, 416, -375, true, 'column', 'bestseller', null, 0),
    ('symposium', 'plato', 'philosophy', '{"az":"Simpozium","en":"Symposium","ru":"Пир"}'::jsonb, '{"az":"Bir ziyafət gecəsində Sokrat və dostları Eros haqqında danışır: bədənin gözəlliyindən Gözəlliyin özünə qədər.","en":"At a drinking party Socrates and his friends speak of Eros, from the beauty of a body to Beauty itself.","ru":"На пиру Сократ и его друзья говорят об Эросе — от красоты тела до самой Красоты."}'::jsonb, 12.5, null, 18, 160, -385, true, 'star', null, null, 1),
    ('apology', 'plato', 'philosophy', '{"az":"Sokratın müdafiəsi","en":"The Apology of Socrates","ru":"Апология Сократа"}'::jsonb, '{"az":"Ölüm hökmü qarşısında Sokratın Afina məhkəməsindəki çıxışı: fəlsəfi həyatın ən cəsarətli müdafiəsi.","en":"Socrates'' speech to the Athenian court as it condemns him: the boldest defence of the philosophical life.","ru":"Речь Сократа перед афинским судом, приговорившим его к смерти: самая смелая защита философской жизни."}'::jsonb, 9.5, null, 30, 96, -399, true, 'laurel', null, null, 2),
    ('nicomachean-ethics', 'aristotle', 'philosophy', '{"az":"Nikomax etikası","en":"Nicomachean Ethics","ru":"Никомахова этика"}'::jsonb, '{"az":"Xoşbəxtlik fəzilətli fəaliyyətdir: Aristotelin xarakter, dostluq və «qızıl orta» haqqında dərsləri.","en":"Happiness is virtuous activity: Aristotle''s lectures on character, friendship and the golden mean.","ru":"Счастье — это добродетельная деятельность: лекции Аристотеля о характере, дружбе и золотой середине."}'::jsonb, 21.5, null, 14, 352, -340, true, 'sun', null, null, 3),
    ('politics', 'aristotle', 'philosophy', '{"az":"Siyasət","en":"Politics","ru":"Политика"}'::jsonb, '{"az":"«İnsan siyasi varlıqdır»: ailədən polisə qədər idarəetmə formalarının ilk sistemli təhlili.","en":"\"Man is a political animal\": the first systematic study of forms of rule, from household to city-state.","ru":"«Человек — существо политическое»: первый систематический анализ форм правления — от семьи до полиса."}'::jsonb, 19.9, null, 9, 320, -350, true, 'column', null, null, 4),
    ('enchiridion', 'epictetus', 'philosophy', '{"az":"Enxiridion","en":"Enchiridion","ru":"Энхиридион"}'::jsonb, '{"az":"Stoisizmin cib kitabçası: bizdən asılı olanla olmayanı ayırmağın yığcam və sərt təlimatı.","en":"The pocket handbook of Stoicism: a terse guide to telling what is up to us from what is not.","ru":"Карманное руководство стоицизма: краткое наставление о том, как отличать зависящее от нас от не зависящего."}'::jsonb, 9.9, null, 40, 88, 125, true, 'laurel', 'new', null, 5),
    ('meditations', 'marcus-aurelius', 'philosophy', '{"az":"Düşüncələr","en":"Meditations","ru":"Размышления"}'::jsonb, '{"az":"Roma imperatorunun yalnız özü üçün yazdığı qeydlər: vəzifə, ölüm və sakitlik haqqında.","en":"Notes a Roman emperor wrote only for himself, on duty, death and calm.","ru":"Записи римского императора, сделанные только для себя: о долге, смерти и спокойствии."}'::jsonb, 13.9, 17.5, 35, 224, 180, true, 'laurel', 'bestseller', null, 6),
    ('letters-to-lucilius', 'seneca', 'philosophy', '{"az":"Lusiliyə əxlaqi məktublar","en":"Letters to Lucilius","ru":"Нравственные письма к Луцилию"}'::jsonb, '{"az":"Gənc dosta yazılmış yüz iyirmi dörd məktub: zamanı qorumaq, qorxunu yenmək və yaxşı yaşamaq haqqında.","en":"One hundred and twenty-four letters to a younger friend on guarding time, mastering fear and living well.","ru":"Сто двадцать четыре письма младшему другу — о том, как беречь время, побеждать страх и жить достойно."}'::jsonb, 22.9, null, 12, 448, 65, true, 'quill', null, null, 7),
    ('discourse-on-method', 'descartes', 'philosophy', '{"az":"Metod haqqında mühakimə","en":"Discourse on the Method","ru":"Рассуждение о методе"}'::jsonb, '{"az":"Ağlı düzgün istiqamətləndirmək üçün dörd qayda və «Düşünürəm, deməli, varam» kəşfinə aparan yol.","en":"Four rules for rightly conducting reason, and the road to \"I think, therefore I am\".","ru":"Четыре правила для верного руководства разумом и путь к открытию «Я мыслю, следовательно, существую»."}'::jsonb, 11.5, null, 20, 128, 1637, false, 'compass', null, null, 8),
    ('ethics', 'spinoza', 'philosophy', '{"az":"Etika","en":"Ethics","ru":"Этика"}'::jsonb, '{"az":"Həndəsi qaydada sübut olunmuş fəlsəfə: Tanrı, ağıl, ehtiraslar və insan azadlığı haqqında.","en":"Philosophy demonstrated in geometric order: on God, the mind, the passions and human freedom.","ru":"Философия, доказанная в геометрическом порядке: о Боге, уме, аффектах и человеческой свободе."}'::jsonb, 24.9, null, 7, 368, 1677, false, 'compass', null, null, 9),
    ('critique-of-pure-reason', 'kant', 'philosophy', '{"az":"Xalis ağlın tənqidi","en":"Critique of Pure Reason","ru":"Критика чистого разума"}'::jsonb, '{"az":"Nəyi bilə bilərik? Məkan, zaman və kateqoriyaların təcrübəni necə formalaşdırdığını göstərən çevriliş.","en":"What can we know? The revolution showing how space, time and the categories shape experience.","ru":"Что мы можем знать? Переворот, показавший, как пространство, время и категории формируют опыт."}'::jsonb, 32, null, 6, 784, 1781, false, 'star', null, null, 10),
    ('phenomenology-of-spirit', 'hegel', 'philosophy', '{"az":"Ruhun fenomenologiyası","en":"Phenomenology of Spirit","ru":"Феноменология духа"}'::jsonb, '{"az":"Şüurun sadə hiss qavrayışından mütləq biliyə qədər yolu; ağa və qul dialektikası da buradadır.","en":"Consciousness on its way from bare sensation to absolute knowing, master and slave dialectic included.","ru":"Путь сознания от чувственной достоверности к абсолютному знанию, включая диалектику господина и раба."}'::jsonb, 24.5, 29, 8, 640, 1807, false, 'sun', null, null, 11),
